window.MNEMIKA_LIFE_BASICS={"version":"7.1.0","content_revision":"r159-audit-2026-11-07","status":"INSTALLED_R160_EDITORIAL_REPLACEMENT_SPECIALIST_REVIEW_PENDING","notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","scope":"Vereinfachte Lern-Nachbildung, kein amtliches Formular und nicht für eine Zahlung, Erklärung oder einen Antrag verwendbar.","lessons":[{"id":"gl-01","nr":1,"kurz":"Lohnabrechnung","titel":"Deine Lohnabrechnung lesen","bild":"💰","wozu":"Du unterscheidest im Muster Lohn, Abzüge und Auszahlung und rechnest die Beträge nach.","einstieg":"Eine Lohnabrechnung erklärt den Weg vom vereinbarten Bruttolohn zur Auszahlung. Im erfundenen Beispiel erhält Lea auch belegte Reisekosten zurück. Deshalb ist ihre Bankzahlung höher als ihr Nettolohn. Die verwendeten Abzüge sind Angaben dieses Musters, keine persönliche Lohnberechnung.","ziele":["Brutto und netto auseinanderhalten","Die Abzüge AHV, ALV, Unfall und Pensionskasse erkennen","Nachrechnen, ob die Auszahlung stimmt"],"begriffe":[["Bruttolohn","Dein Lohn, bevor etwas abgezogen wird."],["Nettolohn","Was nach den Abzügen übrig bleibt."],["Sozialversicherung","Beiträge unter anderem für Alter, Invalidität, Erwerbsersatz und Arbeitslosigkeit. Die Leistungen haben eigene Voraussetzungen."],["Spesen","Im Muster: Rückerstattung nachgewiesener Geschäftsauslagen. Nicht jede als Spesen bezeichnete Zahlung wird gleich behandelt."]],"doc":{"art":"Lohnabrechnung","kopfL":["Velowerk Muster AG","Industriestrasse 12","8000 Zürich"],"kopfR":["Lea Beispiel","Seeweg 4","8706 Meilen"],"titel":"Lohnabrechnung März 2027","unter":"Personal-Nr. 1042 · Pensum 100 %","teile":[{"t":"zeilen","zeilen":[["Monatslohn (brutto)","4’600.00",1,"stark"],["AHV / IV / EO 5,3 %","− 243.80",2],["ALV 1,1 %","− 50.60",3],["NBU (Nichtberufsunfall) 1,2 %","− 55.20",4],["Pensionskasse (BVG)","− 192.50",5],["Nettolohn","4’057.90",6,"stark linie"],["Spesen (Reisekosten)","+ 80.00",7],["Auszahlung","4’137.90",8,"stark doppel"]]},{"t":"kasten","titel":"Überweisung","text":"Musterkonto, nicht zahlbar. Die Datumsangabe gehört zum erfundenen Fall.","n":9}],"fuss":"Vereinfachte Lern-Nachbildung, kein amtliches Formular und nicht für eine Zahlung, Erklärung oder einen Antrag verwendbar. Diese Abrechnung ist ein Muster mit fiktiven Werten. Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","case_date_policy":"Any 2027/2031 date belongs to an invented story, not a claim that future law has been verified. Substantive guidance checked on 2026-11-07."},"tour":[[1,"Ganz oben: der Bruttolohn","Das ist dein vereinbarter Lohn laut Arbeitsvertrag. Davon wird gleich etwas abgezogen."],[2,"AHV / IV / EO","Im Muster werden 5,3 % abgezogen: 4600 × 0,053 = 243.80. Das entspricht dem geprüften Arbeitnehmeransatz; Arbeitgeberbeiträge sind separat. Daraus ergibt sich keine bestimmte persönliche Rente."],[3,"ALV","Im Muster: 4600 × 1,1 % = 50.60. Ein Beitrag allein beweist keinen Anspruch auf Arbeitslosenentschädigung. Für Leistungen gelten weitere Voraussetzungen."],[4,"Nichtberufsunfall","Hier wird ein fiktiver NBU-Abzug von 1,2 % verwendet. Der tatsächliche Satz ist nicht bei allen Betrieben gleich. Die obligatorische Freizeitunfalldeckung hängt unter anderem von mindestens acht Wochenstunden beim selben Arbeitgeber ab."],[5,"Pensionskasse","Im Muster beträgt der Abzug 192.50. Ein Pensionskassenbeitrag kann Spar-, Risiko- und Kostenbestandteile enthalten. Das Reglement und der Vorsorgeausweis erklären den konkreten Plan."],[6,"Nettolohn","Brutto minus alle Abzüge. 4’600.00 − 542.10 = 4’057.90."],[7,"Belegte Spesen","Lea erhält in diesem Fall 80 Franken für zuvor bezahlte Geschäftsreisen zurück. Diese Erstattung ist kein zusätzlicher Lohn. Andere Spesenarten brauchen eine eigene Einordnung."],[8,"Auszahlung","Nur für dieses Muster: 4057.90 Nettolohn + 80.00 Spesenersatz = 4137.90 Bankzahlung."],[9,"Konto und Buchung","Das Muster enthält keine nutzbare Kontonummer. Bei realen Belegen sind Empfängerangabe, Buchung und Valuta zu unterscheiden. Ein Valutadatum ist nicht automatisch der Zeitpunkt, an dem ein Betrag frei verfügbar wird."]],"beispiel":"Lea rechnet nach: 243.80 + 50.60 + 55.20 + 192.50 = 542.10 Abzüge. 4’600.00 − 542.10 = 4’057.90 Nettolohn. Mit 80.00 Spesen kommen 4’137.90 aufs Konto.","fehler":["Den Bruttolohn mit frei verfügbarem Geld gleichsetzen.","Eine Rückerstattung bereits bezahlter Geschäftsauslagen als zusätzliches Einkommen einplanen.","Aus einem Musterabzug den richtigen Satz für jeden Betrieb ableiten."],"fragen":[{"id":"gl-01-q1","type":"numeric","prompt":"Wie viel zieht die Firma für AHV / IV / EO ab?","answer":243.8,"tolerance":0.01,"unit":"CHF","hint":"Schau auf Zeile 2 der Abrechnung.","explanation":"5,3 % von 4’600 sind 243.80 Franken.","weg":["4’600 × 5,3 % rechnen","4’600 × 0,053 = 243.80"],"source_refs":["CH-BSV-CONTRIB","CH-BAG-UVG","CH-ESTV-SALARY"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-01-document","optional":true,"context":"Eine Lohnabrechnung erklärt den Weg vom vereinbarten Bruttolohn zur Auszahlung. Im erfundenen Beispiel erhält Lea auch belegte Reisekosten zurück. Deshalb ist ihre Bankzahlung höher als ihr Nettolohn. Die verwendeten Abzüge sind Angaben dieses Musters, keine persönliche Lohnberechnung.","context_document_required":true},{"id":"gl-01-q2","type":"numeric","prompt":"Wie gross sind alle Abzüge zusammen?","answer":542.1,"tolerance":0.01,"unit":"CHF","hint":"Zähle die Zeilen 2 bis 5 zusammen.","explanation":"243.80 + 50.60 + 55.20 + 192.50 = 542.10 Franken.","weg":["Nur die Zeilen mit Minus nehmen","243.80 + 50.60 + 55.20 + 192.50 = 542.10"],"source_refs":["CH-BSV-CONTRIB","CH-BAG-UVG","CH-ESTV-SALARY"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-01-document","optional":true,"context":"Eine Lohnabrechnung erklärt den Weg vom vereinbarten Bruttolohn zur Auszahlung. Im erfundenen Beispiel erhält Lea auch belegte Reisekosten zurück. Deshalb ist ihre Bankzahlung höher als ihr Nettolohn. Die verwendeten Abzüge sind Angaben dieses Musters, keine persönliche Lohnberechnung.","context_document_required":true},{"id":"gl-01-q3","type":"mc","prompt":"Warum ist im Muster die Bankzahlung höher als der Nettolohn?","options":["Weil Spesen dazukommen","Weil die Firma einen Bonus zahlt","Weil die AHV zurückbezahlt wird","Weil der Bruttolohn gestiegen ist"],"answer":0,"hint":"Schau auf Zeile 7.","explanation":"Die 80 Franken sind im Fall eine belegte Rückerstattung. 4057.90 + 80 = 4137.90. Das ist kein allgemeiner Beweis, dass jede Spesenposition steuerfrei ist.","source_refs":["CH-BSV-CONTRIB","CH-BAG-UVG","CH-ESTV-SALARY"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-01-document","optional":true,"context":"Eine Lohnabrechnung erklärt den Weg vom vereinbarten Bruttolohn zur Auszahlung. Im erfundenen Beispiel erhält Lea auch belegte Reisekosten zurück. Deshalb ist ihre Bankzahlung höher als ihr Nettolohn. Die verwendeten Abzüge sind Angaben dieses Musters, keine persönliche Lohnberechnung.","context_document_required":true},{"id":"gl-01-q4","type":"mc","prompt":"Welcher wiederkehrende Lohnbetrag eignet sich in diesem Fall als Ausgangspunkt für Leas Budget, ohne den Spesenersatz nochmals als Einkommen zu zählen?","options":["Der Nettolohn ohne den belegten Spesenersatz","Der Bruttolohn","Bruttolohn plus Spesen","Arbeitgeberkosten inklusive Arbeitgeberbeiträgen"],"answer":0,"hint":"Was kann Lea wirklich ausgeben?","explanation":"Im Muster ist 4057.90 der Lohn nach Abzügen. Die 80 Franken ersetzen bereits getätigte Geschäftsauslagen. Weitere Rechnungen und Reserven sind im Budget erst noch zu berücksichtigen.","source_refs":["CH-BSV-CONTRIB","CH-BAG-UVG","CH-ESTV-SALARY"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-01-document","optional":true,"context":"Eine Lohnabrechnung erklärt den Weg vom vereinbarten Bruttolohn zur Auszahlung. Im erfundenen Beispiel erhält Lea auch belegte Reisekosten zurück. Deshalb ist ihre Bankzahlung höher als ihr Nettolohn. Die verwendeten Abzüge sind Angaben dieses Musters, keine persönliche Lohnberechnung.","context_document_required":true}],"vertiefen":["ga-02-01","ga-02-02","ga-02-05"],"source_refs":["CH-BSV-CONTRIB","CH-BAG-UVG","CH-ESTV-SALARY"],"contentRevision":"r159-audit-2026-11-07","reviewStatus":"SOURCE_CHECKED_EDITORIAL_REPLACEMENT_SPECIALIST_REVIEW_PENDING","checkedOn":"2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","context_policy":"Keep the complete fictional document available beside every question; never grade from an unseen case."},{"id":"gl-02","nr":2,"kurz":"Lohnausweis","titel":"Der Lohnausweis für die Steuererklärung","bild":"🧾","wozu":"Du findest im fiktiven Jahresbeleg die Position Nettolohn und unterscheidest sie von einer einzelnen Bankzahlung.","einstieg":"Der Lohnausweis fasst die vom Arbeitgeber bescheinigten Angaben eines Kalenderjahres zusammen. Er ist etwas anderes als die monatliche Lohnabrechnung. Wir lesen einen vereinfachten Jahresbeleg. Ob und wie eine reale Erklärung einzureichen ist, hängt vom zuständigen Verfahren ab.","ziele":["Lohnabrechnung (Monat) und Lohnausweis (Jahr) unterscheiden","Die wichtigsten Ziffern 1, 8, 9, 10, 11 und 13 lesen","Den Nettolohn für die Steuererklärung finden"],"begriffe":[["Lohnausweis","Jahresübersicht deines Lohns für die Steuern."],["Ziffer","Nummeriertes Feld im Formular. Jede Ziffer hat eine feste Bedeutung."],["13. Monatslohn","Ein zusätzlicher Monatslohn pro Jahr, oft im Dezember."]],"doc":{"art":"Lohnausweis","kopfL":["Lohnausweis · Muster","Jahr 2027 · vom 01.01. bis 31.12."],"kopfR":["Lea Beispiel","AHV-Nr. 756.0000.0000.00 (Muster)"],"titel":"Lohnausweis","unter":"Vereinfachte Lern-Nachbildung des Formulars","teile":[{"t":"ziffern","zeilen":[["1","Lohn (13 × 4’600)","59’800",1],["2","Gehaltsnebenleistungen","–",0],["8","Bruttolohn total","59’800",2],["9","Beiträge AHV/IV/EO/ALV/NBUV","− 4’545",3],["10.1","Berufliche Vorsorge 2. Säule, ordentliche Beiträge","− 2’310",4],["11","Nettolohn","52’945",5,"stark"],["13.1.1","Spesen: Reise, Verpflegung","960",6],["15","Bemerkungen","Spesenreglement genehmigt",7]]}],"fuss":"Vereinfachte Lern-Nachbildung, kein amtliches Formular und nicht für eine Zahlung, Erklärung oder einen Antrag verwendbar. Muster mit fiktiven Werten. Beträge auf Franken gerundet. Die 13 Lohnzahlungen sind eine Fallannahme, kein allgemeiner Anspruch. Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","case_date_policy":"Any 2027/2031 date belongs to an invented story, not a claim that future law has been verified. Substantive guidance checked on 2026-11-07."},"tour":[[1,"Ziffer 1: der Lohn","Alle Monatslöhne des Jahres. Hier 13 Löhne, weil es einen 13. Monatslohn gibt: 13 × 4’600 = 59’800."],[2,"Ziffer 8: Bruttolohn total","Alles zusammen, bevor etwas abgezogen wird."],[3,"Ziffer 9: Sozialversicherungen","AHV, IV, EO, ALV und Unfall für das ganze Jahr. Das sind die Abzüge aus den Lohnabrechnungen zusammengezählt."],[4,"Ziffer 10.1: Pensionskasse","Deine Beiträge an die 2. Säule für das ganze Jahr."],[5,"Ziffer 11: Nettolohn","Ziffer 11 zeigt im Muster den bescheinigten Nettolohn von 52945 Franken. Der offizielle Lohnausweis bezeichnet diesen Wert für die Steuererklärung. Die Übung bestimmt weder das persönliche Verfahren noch die ganze Steuerberechnung."],[6,"Ziffer 13: Spesen","Spesen werden aufgeführt, gehören aber nicht zum Lohn."],[7,"Ziffer 15: Bemerkungen","Hier stehen zusätzliche Hinweise der Firma."]],"beispiel":"59’800 (Ziffer 8) − 4’545 (Ziffer 9) − 2’310 (Ziffer 10.1) = 52’945 (Ziffer 11). Diese Zahl übernimmt Lea in die Steuererklärung.","fehler":["Den Bruttolohn (Ziffer 8) statt den Nettolohn (Ziffer 11) eintragen.","Den Lohnausweis wegwerfen. Du brauchst ihn für die Steuern und als Beleg.","Bei zwei Jobs nur einen Lohnausweis eintragen. Jede Stelle gibt einen eigenen Lohnausweis."],"fragen":[{"id":"gl-02-q1","type":"mc","prompt":"Welche Ziffer trägst du in der Steuererklärung als Lohn ein?","options":["Ziffer 11 (Nettolohn)","Ziffer 8 (Bruttolohn)","Ziffer 1 (Lohn)","Ziffer 13 (Spesen)"],"answer":0,"hint":"Gesucht ist der Lohn nach den Abzügen.","explanation":"In die Steuererklärung gehört der Nettolohn aus Ziffer 11.","source_refs":["CH-ESTV-SALARY"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-02-document","optional":true,"context":"Der Lohnausweis fasst die vom Arbeitgeber bescheinigten Angaben eines Kalenderjahres zusammen. Er ist etwas anderes als die monatliche Lohnabrechnung. Wir lesen einen vereinfachten Jahresbeleg. Ob und wie eine reale Erklärung einzureichen ist, hängt vom zuständigen Verfahren ab.","context_document_required":true},{"id":"gl-02-q2","type":"numeric","prompt":"Wie hoch ist der Nettolohn in Ziffer 11?","answer":52945,"tolerance":0.5,"unit":"CHF","hint":"Ziffer 8 minus Ziffer 9 minus Ziffer 10.1.","explanation":"59’800 − 4’545 − 2’310 = 52’945 Franken.","weg":["Mit Ziffer 8 starten: 59’800","4’545 und 2’310 abziehen","Ergebnis 52’945"],"source_refs":["CH-ESTV-SALARY"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-02-document","optional":true,"context":"Der Lohnausweis fasst die vom Arbeitgeber bescheinigten Angaben eines Kalenderjahres zusammen. Er ist etwas anderes als die monatliche Lohnabrechnung. Wir lesen einen vereinfachten Jahresbeleg. Ob und wie eine reale Erklärung einzureichen ist, hängt vom zuständigen Verfahren ab.","context_document_required":true},{"id":"gl-02-q3","type":"mc","prompt":"Was ist der Unterschied zwischen Lohnabrechnung und Lohnausweis?","options":["Die Lohnabrechnung gilt für einen Monat, der Lohnausweis für ein ganzes Jahr","Es ist dasselbe Papier mit anderem Namen","Den Lohnausweis gibt es nur für Selbständige","Die Lohnabrechnung ist für die Steuern, der Lohnausweis für die Bank"],"answer":0,"hint":"Denk an den Zeitraum.","explanation":"Die Lohnabrechnung kommt jeden Monat. Der Lohnausweis fasst das Jahr zusammen und ist für die Steuern.","source_refs":["CH-ESTV-SALARY"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-02-document","optional":true,"context":"Der Lohnausweis fasst die vom Arbeitgeber bescheinigten Angaben eines Kalenderjahres zusammen. Er ist etwas anderes als die monatliche Lohnabrechnung. Wir lesen einen vereinfachten Jahresbeleg. Ob und wie eine reale Erklärung einzureichen ist, hängt vom zuständigen Verfahren ab.","context_document_required":true}],"vertiefen":["ga-02-03","ga-07-01","ga-07-02"],"source_refs":["CH-ESTV-SALARY"],"contentRevision":"r159-audit-2026-11-07","reviewStatus":"SOURCE_CHECKED_EDITORIAL_REPLACEMENT_SPECIALIST_REVIEW_PENDING","checkedOn":"2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","context_policy":"Keep the complete fictional document available beside every question; never grade from an unseen case."},{"id":"gl-03","nr":3,"kurz":"QR-Rechnung","titel":"Eine QR-Rechnung lesen und Angaben vergleichen","bild":"📮","wozu":"Du findest Betrag, Empfänger und Referenz im Muster und erkennst, was ein QR-Code nicht beweist.","einstieg":"Ein QR-Code überträgt Zahlungsangaben. Er bestätigt nicht, dass eine Forderung berechtigt oder eine Nachricht echt ist. Diese Lern-Nachbildung hat keinen nutzbaren Zahlungscode. Du vergleichst die Angaben des erfundenen Belegs; es wird keine Zahlung ausgelöst.","ziele":["Empfangsschein und Zahlteil unterscheiden","Empfänger, Konto, Referenz und Betrag finden","Vor dem Bezahlen die richtigen Punkte prüfen"],"begriffe":[["QR-Rechnung","Rechnung mit Zahlteil und QR-Code. Sie hat die alten Einzahlungsscheine ersetzt."],["IBAN","Kontonummer. Schweizer IBAN beginnen mit CH."],["Referenz","Nummer, an der der Empfänger erkennt, welche Rechnung du bezahlst."]],"doc":{"art":"qr","kopfL":["Elektrizitätswerk Muster","Seestrasse 1, 8000 Zürich"],"kopfR":["Rechnung Nr. 47-1182","Fällig am 30.04.2027"],"titel":"Stromrechnung 1. Quartal 2027","unter":"Lea Beispiel, Seeweg 4, 8706 Meilen","teile":[{"t":"zeilen","zeilen":[["Energie 412 kWh","103.00"],["Netznutzung","61.80"],["Abgaben","8.20"],["MWST 8,1 %","13.40"],["Total","186.40",1,"stark linie"]]},{"t":"qrteil","konto":"MUSTERKONTO - NICHT ZAHLBAR","an":["Elektrizitätswerk Muster","Seestrasse 1","8000 Zürich"],"ref":"21 00000 00003 13947 14300 09017","info":"Rechnung 47-1182","durch":["Lea Beispiel","Seeweg 4","8706 Meilen"],"betrag":"186.40","nKonto":2,"nRef":3,"nBetrag":4,"nDurch":5,"nQr":6,"nEmpf":7}],"fuss":"Vereinfachte Lern-Nachbildung, kein amtliches Formular und nicht für eine Zahlung, Erklärung oder einen Antrag verwendbar. Muster: Der QR-Code ist nicht scannbar. Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","case_date_policy":"Any 2027/2031 date belongs to an invented story, not a claim that future law has been verified. Substantive guidance checked on 2026-11-07."},"tour":[[1,"Oben: die Rechnung","Hier steht, wofür du bezahlst und wann die Rechnung fällig ist."],[7,"Empfangsschein","Der abtrennbare Empfangsschein dient beim Schalterverfahren als Beleg. Er ersetzt nicht die Prüfung einer Forderung."],[6,"Code als Datenbehälter","Der echte Swiss QR Code enthält Zahlungsinformationen. Ein Kreuz oder Logo allein beweist keine Echtheit. Das Bild hier ist eine schematische Illustration und nicht zum Scannen bestimmt."],[2,"Konto und Zahlungsempfänger","Hier werden im echten Zahlteil Konto und Empfänger aufgeführt. Gleiche Angaben im Code und auf einer Rechnung beweisen allein noch nicht, dass die Forderung stimmt."],[3,"Referenz","Die Referenz dient der Zuordnung einer Zahlung. SIX unterscheidet QR-IBAN mit QR-Referenz sowie IBAN mit Creditor Reference oder ohne Referenz. Dieses Muster erzeugt keine normgerechte Zahlungsreferenz."],[5,"Rechnungsempfängerin","In diesem Fall ist Lea als Person aufgeführt, an die die Rechnung adressiert ist."],[4,"Betrag","Der erfundene Beleg nennt 186.40 Franken. Die Aufgabe ist ein Zahlenvergleich, kein Zahlungsauftrag."]],"beispiel":"Im Muster stehen oben und im Zahlteil je 186.40 Franken. Diese Übereinstimmung ist eine Kontrolle, aber kein Echtheitsbeweis. Lea würde auch den Absender und den Anlass unabhängig mit ihren Unterlagen abgleichen. Die Lernseite kann weder einen Code als sicher bestätigen noch bezahlen.","fehler":["Ein Schweizerkreuz oder ein bekanntes Logo mit einem Echtheitsnachweis verwechseln.","Nur zwei gleiche Beträge vergleichen und den Anlass der Rechnung nicht prüfen.","Einen Lern-Code oder ein Musterkonto für eine wirkliche Zahlung verwenden."],"fragen":[{"id":"gl-03-q1","type":"numeric","prompt":"Welcher Betrag steht auf der fiktiven Rechnung?","answer":186.4,"tolerance":0.01,"unit":"CHF","hint":"Feld «Betrag» im Zahlteil.","explanation":"Im Zahlteil und beim Total steht 186.40. Die Aufgabe liest nur den Beleg und bestätigt keinen realen Zahlungsanspruch.","source_refs":["CH-SIX-QR","CH-SIX-FAQ"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-03-document","optional":true,"context":"Ein QR-Code überträgt Zahlungsangaben. Er bestätigt nicht, dass eine Forderung berechtigt oder eine Nachricht echt ist. Diese Lern-Nachbildung hat keinen nutzbaren Zahlungscode. Du vergleichst die Angaben des erfundenen Belegs; es wird keine Zahlung ausgelöst.","context_document_required":true},{"id":"gl-03-q2","type":"mc","prompt":"Welche Kontrolle ist beim fiktiven Beispiel sinnvoll?","options":["Empfänger, Betrag und Rechnungsanlass mit unabhängigen Unterlagen vergleichen","Dem Schweizerkreuz als Echtheitsbeweis vertrauen","Nur die Anzahl Ziffern der Referenz zählen","Nur die Farbe des Papiers prüfen"],"answer":0,"hint":"Wem schickst du Geld?","explanation":"Ein Code kann falsche Angaben enthalten. Form und Logo sind kein Echtheitsnachweis. Im Beispiel geht es um unabhängige Prüfung, nicht um eine Zahlungsfreigabe.","source_refs":["CH-SIX-QR","CH-SIX-FAQ"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-03-document","optional":true,"context":"Ein QR-Code überträgt Zahlungsangaben. Er bestätigt nicht, dass eine Forderung berechtigt oder eine Nachricht echt ist. Diese Lern-Nachbildung hat keinen nutzbaren Zahlungscode. Du vergleichst die Angaben des erfundenen Belegs; es wird keine Zahlung ausgelöst.","context_document_required":true},{"id":"gl-03-q3","type":"mc","prompt":"Wofür ist der Empfangsschein links?","options":["Als Beleg, wenn du am Postschalter bezahlst","Damit die Bank den Betrag kennt","Für die Steuererklärung","Er muss immer mitgeschickt werden"],"answer":0,"hint":"Wo bekommst du einen Stempel?","explanation":"Am Schalter wird der Empfangsschein abgestempelt. Beim E-Banking brauchst du ihn nicht.","source_refs":["CH-SIX-QR","CH-SIX-FAQ"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-03-document","optional":true,"context":"Ein QR-Code überträgt Zahlungsangaben. Er bestätigt nicht, dass eine Forderung berechtigt oder eine Nachricht echt ist. Diese Lern-Nachbildung hat keinen nutzbaren Zahlungscode. Du vergleichst die Angaben des erfundenen Belegs; es wird keine Zahlung ausgelöst.","context_document_required":true}],"vertiefen":["ga-03-02","ga-11-03","ga-22-03"],"source_refs":["CH-SIX-QR","CH-SIX-FAQ"],"contentRevision":"r159-audit-2026-11-07","reviewStatus":"SOURCE_CHECKED_EDITORIAL_REPLACEMENT_SPECIALIST_REVIEW_PENDING","checkedOn":"2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","context_policy":"Keep the complete fictional document available beside every question; never grade from an unseen case."},{"id":"gl-04","nr":4,"kurz":"Kontoauszug","titel":"Kontoauszug lesen und ein Budget starten","bild":"🏦","wozu":"Du siehst, wohin dein Geld fliesst, und trennst feste von variablen Kosten.","einstieg":"Ein Kontoauszug zeigt Buchungen und Salden. Für ein Budget musst du zusätzlich wissen, wofür die Zahlungen bestimmt sind. Im erfundenen Fall sind Miete, Prämie und Handy-Abonnement feste Monatsbeträge; zwei Freizeitausgaben schwanken. Die Zahlungsart allein verrät diese Einordnung nicht.","ziele":["Gutschriften und Belastungen erkennen","Den Saldo nachrechnen","Fixkosten und variable Ausgaben trennen"],"begriffe":[["Gutschrift","Geld kommt aufs Konto."],["Belastung","Geld geht vom Konto weg."],["Saldo","Kontostand nach einer Buchung."],["Dauerauftrag","Zahlung, die du einmal einrichtest und die jeden Monat automatisch läuft."],["LSV / eBill","Rechnung, die automatisch bezahlt oder digital zur Freigabe geschickt wird."]],"doc":{"art":"Kontoauszug","kopfL":["Bank Muster AG","Privatkonto MUSTERKONTO - NICHT ZAHLBAR"],"kopfR":["Lea Beispiel","Auszug März 2027"],"titel":"Kontoauszug 01.03.–31.03.2027","unter":"Alle Beträge in CHF","teile":[{"t":"tabelle","kopf":["Datum","Text","Belastung","Gutschrift","Saldo"],"zeilen":[["01.03.","Saldovortrag","","","1’250.30",1],["03.03.","Dauerauftrag Miete Muster Immobilien","1’430.00","","−179.70",2],["05.03.","Krankenkasse Muster (LSV)","389.50","","−569.20",3],["12.03.","TWINT an M. Freund","24.00","","−593.20",4],["18.03.","Karte: Migros Meilen","86.45","","−679.65",5],["20.03.","eBill Swisscom","59.90","","−739.55",6],["25.03.","Lohn Velowerk Muster AG","","4’137.90","3’398.35",7]]}],"fuss":"Vereinfachte Lern-Nachbildung, kein amtliches Formular und nicht für eine Zahlung, Erklärung oder einen Antrag verwendbar. Muster mit fiktiven Buchungen. Ein negativer Saldo kostet bei vielen Banken Zinsen. Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","case_date_policy":"Any 2027/2031 date belongs to an invented story, not a claim that future law has been verified. Substantive guidance checked on 2026-11-07."},"tour":[[1,"Saldovortrag","Damit startet der Monat. So viel war am Ende des letzten Monats auf dem Konto."],[2,"Miete im Fall","Hier ist eine gleichbleibende Monatsmiete vereinbart. Ein Dauerauftrag allein macht eine Ausgabe nicht automatisch fix."],[3,"Versicherungsprämie im Fall","Der Betrag ist in diesem Muster monatlich gleich. Andere Belastungen beim gleichen Zahlungsweg können variieren."],[4,"TWINT-Zahlung","Im Fall bezahlt Lea einen wechselnden Freizeitanteil. TWINT ist nur der Zahlungsweg und kann ebenso für feste oder geschäftliche Ausgaben verwendet werden."],[5,"Kartenzahlung","Dieser Eintrag ist laut Fallbeschreibung ein veränderlicher Einkauf. Die Karte selbst sagt nichts über die Budgetkategorie aus."],[6,"Handy-Abonnement","Im Fall ist 59.90 der vereinbarte Monatsbetrag. eBill ist die Zustell- und Zahlungsform, nicht die Kostenart."],[7,"Zeitpunkt der Einnahme","Die Gutschrift kommt im Beispiel erst am 25. Der negative Zwischensaldo zeigt ein zeitliches Problem. Das ist keine Annahme, dass ein reales Konto eine Überziehung erlauben würde."]],"beispiel":"Fixkosten: Miete 1’430.00 + Krankenkasse 389.50 + Handy 59.90 = 1’879.40 pro Monat. Diese Summe muss Lea immer einplanen, bevor sie etwas anderes ausgibt.","fehler":["Nur auf den Saldo schauen. Lies auch, wofür das Geld weggeht.","Kleine Beträge übersehen. Viele kleine Zahlungen machen zusammen viel aus.","Kein Polster haben, bis der Lohn kommt."],"fragen":[{"id":"gl-04-q1","type":"numeric","prompt":"Wie hoch sind Leas Fixkosten (Miete, Krankenkasse, Handy) zusammen?","answer":1879.4,"tolerance":0.01,"unit":"CHF","hint":"Zeilen 2, 3 und 6.","explanation":"1’430.00 + 389.50 + 59.90 = 1’879.40 Franken.","source_refs":["ORIGINAL-ARITHMETIC"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-04-document","optional":true,"context":"Ein Kontoauszug zeigt Buchungen und Salden. Für ein Budget musst du zusätzlich wissen, wofür die Zahlungen bestimmt sind. Im erfundenen Fall sind Miete, Prämie und Handy-Abonnement feste Monatsbeträge; zwei Freizeitausgaben schwanken. Die Zahlungsart allein verrät diese Einordnung nicht.","context_document_required":true},{"id":"gl-04-q2","type":"numeric","prompt":"Wie viel ist am 31.03. auf dem Konto?","answer":3398.35,"tolerance":0.01,"unit":"CHF","hint":"Letzte Zeile, Spalte Saldo.","explanation":"Nach der Lohngutschrift steht der Saldo bei 3’398.35 Franken.","source_refs":["ORIGINAL-ARITHMETIC"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-04-document","optional":true,"context":"Ein Kontoauszug zeigt Buchungen und Salden. Für ein Budget musst du zusätzlich wissen, wofür die Zahlungen bestimmt sind. Im erfundenen Fall sind Miete, Prämie und Handy-Abonnement feste Monatsbeträge; zwei Freizeitausgaben schwanken. Die Zahlungsart allein verrät diese Einordnung nicht.","context_document_required":true},{"id":"gl-04-q3","type":"selection","prompt":"Welche zwei Ausgaben sind laut der ausdrücklichen Fallbeschreibung variabel?","options":["Wechselnder Freizeitanteil, mit TWINT bezahlt","Veränderlicher Einkauf, mit Karte bezahlt","Vereinbarte Monatsmiete","Monatlich gleichbleibende Versicherungsprämie"],"answers":[0,1],"hint":"Variabel heisst: jeden Monat anders.","explanation":"Die Fallbeschreibung, nicht TWINT oder Karte, legt hier die Kategorie fest. Ein Zahlungsweg kann verschiedene Kostenarten abwickeln.","source_refs":["ORIGINAL-ARITHMETIC"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-04-document","optional":true,"context":"Ein Kontoauszug zeigt Buchungen und Salden. Für ein Budget musst du zusätzlich wissen, wofür die Zahlungen bestimmt sind. Im erfundenen Fall sind Miete, Prämie und Handy-Abonnement feste Monatsbeträge; zwei Freizeitausgaben schwanken. Die Zahlungsart allein verrät diese Einordnung nicht.","context_document_required":true}],"vertiefen":["ga-01-01","ga-01-02","ga-03-01"],"source_refs":["ORIGINAL-ARITHMETIC"],"contentRevision":"r159-audit-2026-11-07","reviewStatus":"SOURCE_CHECKED_EDITORIAL_REPLACEMENT_SPECIALIST_REVIEW_PENDING","checkedOn":"2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","context_policy":"Keep the complete fictional document available beside every question; never grade from an unseen case."},{"id":"gl-05","nr":5,"kurz":"Krankenkasse","titel":"Die Krankenkassen-Police verstehen","bild":"🩺","wozu":"Du unterscheidest Prämie, Franchise und Selbstbehalt in einem begrenzten Erwachsenen-Beispiel.","einstieg":"Lea ist im erfundenen Fall eine erwachsene Person mit Schweizer Grundversicherung. Die Police nennt Prämie, Modell und Franchise. Für die Rechenbeispiele gelten gewöhnliche gedeckte ambulante Kosten: keine Spitaltage, keine besonderen Medikamentenregeln und keine Ausnahme wie Mutterschaft. Das ist keine Auswahl einer passenden Versicherung.","ziele":["Prämie, Franchise und Selbstbehalt unterscheiden","Das Versicherungsmodell erkennen","Verstehen, warum die Unfalldeckung ausgeschlossen sein kann"],"begriffe":[["Prämie","Betrag, den du jeden Monat bezahlst, auch wenn du gesund bist."],["Franchise","Diesen Betrag pro Jahr bezahlst du zuerst selbst. Für Erwachsene zwischen 300 und 2’500 Franken."],["Selbstbehalt","Danach zahlst du 10 % der Kosten, höchstens 700 Franken im Jahr (Erwachsene)."],["Grundversicherung","Pflicht für alle. Die Leistungen sind gesetzlich gleich."],["Zusatzversicherung","Freiwillig, zum Beispiel für Zahnarzt oder Einzelzimmer."]],"doc":{"art":"Police","kopfL":["Krankenkasse Muster","Postfach, 3000 Bern"],"kopfR":["Lea Beispiel","Versicherten-Nr. 80756 (Muster)"],"titel":"Versicherungspolice 2027","unter":"Gültig ab 01.01.2027","teile":[{"t":"zeilen","zeilen":[["Grundversicherung nach KVG","obligatorisch",1,"stark"],["Versicherungsmodell","Hausarzt-Modell",2],["Franchise pro Jahr","300.00",3],["Selbstbehalt","10 %, max. 700.00 pro Jahr",4],["Unfalldeckung","ausgeschlossen",5],["Prämie pro Monat","389.50",6,"stark linie"],["Zusatzversicherung Zahn (VVG)","nicht abgeschlossen",7]]}],"fuss":"Vereinfachte Lern-Nachbildung, kein amtliches Formular und nicht für eine Zahlung, Erklärung oder einen Antrag verwendbar. Muster mit fiktiven Werten. Prämien hängen von Kanton, Alter, Kasse, Modell und Franchise ab. Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","case_date_policy":"Any 2027/2031 date belongs to an invented story, not a claim that future law has been verified. Substantive guidance checked on 2026-11-07."},"tour":[[1,"Grundversicherung im Fall","Lea unterliegt im Fall der Schweizer Krankenversicherungspflicht. Aufnahme und Leistungen der Grundversicherung sind von Zusatzversicherungen zu unterscheiden. Persönliche Ausnahmen werden hier nicht entschieden."],[2,"Versicherungsmodell","Ein alternatives Modell kann einen vorgeschriebenen ersten Kontakt vorsehen. Der konkrete Vertrag und dessen Ausnahmen sind massgebend. Dieses Muster enthält keine vollständigen Modellbedingungen."],[3,"Franchise","Im Muster gilt eine Jahresfranchise von 300 Franken. Sie wird auf die beschriebenen gedeckten Kosten angewendet. Eine andere Franchise verändert die Rechnung; daraus folgt keine Empfehlung."],[4,"Gewöhnlicher Selbstbehalt","Nach der Franchise verwenden wir hier 10 % Selbstbehalt bis zur gewöhnlichen Erwachsenenobergrenze von 700 Franken. Spitalbeiträge und besondere Medikamentenregeln sind separat; die Aussage «nie mehr als 700» wäre falsch."],[5,"Unfalldeckung im Fall","Für Lea ist volle UVG-Deckung beim Arbeitgeber dokumentiert; sie arbeitet dort mindestens acht Stunden pro Woche. Ein Jobende bedeutet nicht automatisch sofort fehlende Deckung: Nachdeckung und eine mögliche obligatorische Suva-Deckung bei Arbeitslosigkeit sind zu klären. Das Beispiel wählt keine neue Deckung."],[6,"Prämie","389.50 ist hier der erfundene Monatsbetrag. Er fällt unabhängig von den im Beispiel beanspruchten Leistungen an."],[7,"Zusatzversicherung","Eine freiwillige Zusatzversicherung hat andere Aufnahme- und Vertragsbedingungen. Die Aufgabe entscheidet weder ihre Notwendigkeit noch ein konkretes Angebot."]],"beispiel":"Nur im beschriebenen Standardmodell: 12 × 389.50 = 4674 Franken Jahresprämie. Dazu rechnen wir bis zu 300 Franken Franchise und bis zu 700 Franken gewöhnlichen Selbstbehalt. Das ist kein allgemeiner Höchstbetrag aller Gesundheitskosten: Spitalbeiträge, bestimmte Medikamente und nicht gedeckte Leistungen können anders behandelt werden.","fehler":["Die Prämie mit allen Gesundheitskosten gleichsetzen.","Eine vereinfachte Rechnung auf Spitaltage, besondere Medikamente oder nicht gedeckte Leistungen übertragen.","Aus einem Stellenwechsel automatisch auf eine Versicherungslücke oder die passende Police schliessen."],"fragen":[{"id":"gl-05-q1","type":"numeric","prompt":"Wie viel Prämie zahlt Lea im ganzen Jahr?","answer":4674,"tolerance":0.01,"unit":"CHF","hint":"12 × Monatsprämie.","explanation":"12 × 389.50 = 4’674 Franken.","source_refs":["CH-BAG-COST","CH-BAG-DRUG","CH-BAG-UVG","CH-SUVA-UNEMPLOYED"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-05-document","optional":true,"context":"Lea ist im erfundenen Fall eine erwachsene Person mit Schweizer Grundversicherung. Die Police nennt Prämie, Modell und Franchise. Für die Rechenbeispiele gelten gewöhnliche gedeckte ambulante Kosten: keine Spitaltage, keine besonderen Medikamentenregeln und keine Ausnahme wie Mutterschaft. Das ist keine Auswahl einer passenden Versicherung.","context_document_required":true},{"id":"gl-05-q2","type":"mc","prompt":"Welche im Muster dokumentierte Voraussetzung erklärt die sistierte Unfalldeckung der Grundversicherung?","options":["Volle UVG-Deckung bei Leas Arbeitgeber mit mindestens acht Wochenstunden dort","Junge Menschen haben keine Unfälle","Jede Zusatzversicherung ersetzt automatisch die UVG-Deckung","Das Hausarzt-Modell ersetzt eine Unfallversicherung"],"answer":0,"hint":"Die Voraussetzung ist im Muster ausdrücklich angegeben.","explanation":"Der Fall gibt volle UVG-Deckung und mindestens acht Wochenstunden beim selben Arbeitgeber vor. Ohne diese Angaben darf die Lernseite keine persönliche Deckung beurteilen.","source_refs":["CH-BAG-COST","CH-BAG-DRUG","CH-BAG-UVG","CH-SUVA-UNEMPLOYED"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-05-document","optional":true,"context":"Lea ist im erfundenen Fall eine erwachsene Person mit Schweizer Grundversicherung. Die Police nennt Prämie, Modell und Franchise. Für die Rechenbeispiele gelten gewöhnliche gedeckte ambulante Kosten: keine Spitaltage, keine besonderen Medikamentenregeln und keine Ausnahme wie Mutterschaft. Das ist keine Auswahl einer passenden Versicherung.","context_document_required":true},{"id":"gl-05-q3","type":"mc","prompt":"Welche grundsätzliche Gegenleistung beschreibt eine höhere Wahlfranchise, bei sonst vergleichbarem Angebot?","options":["Möglicher Prämienrabatt gegen höhere Kostenbeteiligung bis zur gewählten Franchise","Automatisch höhere Prämie","Gar kein Selbstbehalt mehr","Automatisch mehr versicherte Leistungen"],"answer":0,"hint":"Prämie und Kostenbeteiligung sind verschiedene Grössen.","explanation":"Die Aufgabe erklärt den Mechanismus, nicht welche Franchise jemand wählen soll. Entscheidend für eine reale Gegenüberstellung sind das konkrete Angebot und dessen Bedingungen.","source_refs":["CH-BAG-COST","CH-BAG-DRUG","CH-BAG-UVG","CH-SUVA-UNEMPLOYED"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-05-document","optional":true,"context":"Lea ist im erfundenen Fall eine erwachsene Person mit Schweizer Grundversicherung. Die Police nennt Prämie, Modell und Franchise. Für die Rechenbeispiele gelten gewöhnliche gedeckte ambulante Kosten: keine Spitaltage, keine besonderen Medikamentenregeln und keine Ausnahme wie Mutterschaft. Das ist keine Auswahl einer passenden Versicherung.","context_document_required":true}],"vertiefen":["ga-05-01","ga-05-02","ga-05-03"],"source_refs":["CH-BAG-COST","CH-BAG-DRUG","CH-BAG-UVG","CH-SUVA-UNEMPLOYED"],"contentRevision":"r159-audit-2026-11-07","reviewStatus":"SOURCE_CHECKED_EDITORIAL_REPLACEMENT_SPECIALIST_REVIEW_PENDING","checkedOn":"2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","context_policy":"Keep the complete fictional document available beside every question; never grade from an unseen case."},{"id":"gl-06","nr":6,"kurz":"Arztrechnung","titel":"Arztrechnung und Leistungsabrechnung","bild":"🧮","wozu":"Du verstehst, warum du einen Teil der Arztrechnung selbst bezahlst und wie viel.","einstieg":"Diese Rechnung betrifft Lea, eine erwachsene fiktive Versicherte. Alle 420 Franken sind im Fall gedeckte ambulante Behandlungskosten. Ihre Franchise von 300 Franken ist noch ganz offen; der gewöhnliche Selbstbehalt ist noch nicht ausgeschöpft. Wir lassen Spitaltage, besondere Medikamente und Ausnahmen ausdrücklich weg.","ziele":["Franchise und Selbstbehalt in einer echten Rechnung erkennen","Deinen Anteil selbst ausrechnen","Tiers garant und Tiers payant unterscheiden"],"begriffe":[["Leistungsabrechnung","Abrechnung der Kasse: wer wie viel bezahlt."],["Tiers garant","Du bezahlst den Arzt und bekommst von der Kasse Geld zurück."],["Tiers payant","Die Kasse bezahlt direkt und verlangt deinen Anteil von dir."]],"doc":{"art":"Leistungsabrechnung","kopfL":["Krankenkasse Muster","Leistungen"],"kopfR":["Lea Beispiel","Abrechnung vom 12.05.2027"],"titel":"Leistungsabrechnung","unter":"Rechnung Dr. med. A. Muster, Hausarztpraxis, Behandlung 02.05.2027","teile":[{"t":"zeilen","zeilen":[["Rechnungsbetrag","420.00",1,"stark"],["davon Franchise (noch offen: 300.00)","− 300.00",2],["verbleibend","120.00",3],["Selbstbehalt 10 % von 120.00","− 12.00",4],["Leistung der Krankenkasse","108.00",5,"stark linie"],["Ihr Anteil (Franchise + Selbstbehalt)","312.00",6,"stark doppel"]]},{"t":"kasten","titel":"Abrechnungsart: Tiers payant","text":"Wir haben die Rechnung direkt bezahlt. Bitte überweisen Sie uns Ihren Anteil von 312.00 innert 30 Tagen.","n":7}],"fuss":"Vereinfachte Lern-Nachbildung, kein amtliches Formular und nicht für eine Zahlung, Erklärung oder einen Antrag verwendbar. Muster mit fiktiven Werten. Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","case_date_policy":"Any 2027/2031 date belongs to an invented story, not a claim that future law has been verified. Substantive guidance checked on 2026-11-07."},"tour":[[1,"Rechnungsbetrag","So viel hat der Arztbesuch gekostet."],[2,"Franchise","Es ist der erste Arztbesuch im Jahr. Die ganze Franchise von 300 Franken ist noch offen. Diese zahlt Lea selbst."],[3,"Was übrig bleibt","420 − 300 = 120 Franken."],[4,"Selbstbehalt","Von diesen 120 Franken zahlt Lea 10 %, also 12 Franken."],[5,"Die Kasse zahlt","Den Rest: 120 − 12 = 108 Franken."],[6,"Leas Anteil","Franchise plus Selbstbehalt: 300 + 12 = 312 Franken."],[7,"Wer zahlt zuerst?","Bei Tiers payant hat die Kasse schon bezahlt und schickt Lea jetzt eine Rechnung über ihren Anteil."]],"beispiel":"Für einen weiteren gedeckten Besuch von 200 Franken im selben Behandlungsjahr ist die Franchise im Fall bereits ausgeschöpft und die gewöhnliche Selbstbehaltsgrenze noch nicht erreicht. Dann ergibt das Modell 200 × 10 % = 20 Franken eigenen Anteil und 180 Franken Versicherungsanteil.","fehler":["Franchise und Selbstbehalt verwechseln.","Die Rechnung ohne Behandlungsjahr oder bisherigen Stand der Kostenbeteiligung prüfen.","Ein einfaches ambulantes Beispiel als Grenze für alle Gesundheitskosten verwenden."],"fragen":[{"id":"gl-06-q1","type":"numeric","prompt":"Wie viel bezahlt Lea selbst für diesen Arztbesuch?","answer":312,"tolerance":0.01,"unit":"CHF","hint":"Franchise plus Selbstbehalt.","explanation":"300 Franken Franchise + 12 Franken Selbstbehalt = 312 Franken.","weg":["Franchise: 300","Rest: 420 − 300 = 120","10 % von 120 = 12","300 + 12 = 312"],"source_refs":["CH-BAG-COST"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-06-document","optional":true,"context":"Diese Rechnung betrifft Lea, eine erwachsene fiktive Versicherte. Alle 420 Franken sind im Fall gedeckte ambulante Behandlungskosten. Ihre Franchise von 300 Franken ist noch ganz offen; der gewöhnliche Selbstbehalt ist noch nicht ausgeschöpft. Wir lassen Spitaltage, besondere Medikamente und Ausnahmen ausdrücklich weg.","context_document_required":true},{"id":"gl-06-q2","type":"numeric","prompt":"Im selben Fall: Ein weiterer gedeckter ambulanter Besuch kostet 200 Franken. Die Franchise ist bezahlt und die gewöhnliche Selbstbehaltsgrenze noch nicht erreicht. Wie hoch ist der eigene Anteil im Modell?","answer":20,"tolerance":0.01,"unit":"CHF","hint":"Nur noch der Selbstbehalt.","explanation":"Unter genau diesen Annahmen: 200 × 0,10 = 20 Franken. Der Wert gilt nicht automatisch bei anderen Regeln oder bereits erreichter Grenze.","source_refs":["CH-BAG-COST"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-06-document","optional":true,"context":"Diese Rechnung betrifft Lea, eine erwachsene fiktive Versicherte. Alle 420 Franken sind im Fall gedeckte ambulante Behandlungskosten. Ihre Franchise von 300 Franken ist noch ganz offen; der gewöhnliche Selbstbehalt ist noch nicht ausgeschöpft. Wir lassen Spitaltage, besondere Medikamente und Ausnahmen ausdrücklich weg.","context_document_required":true},{"id":"gl-06-q3","type":"mc","prompt":"Welche Zahlungsbeziehung beschreibt das Grundprinzip «Tiers garant»?","options":["Die versicherte Person schuldet dem Leistungserbringer die Rechnung und verlangt den gedeckten Anteil von der Kasse zurück","Die Kasse zahlt immer alles ohne Kostenbeteiligung","Der Leistungserbringer hat keinen Zahlungsanspruch","Die Rechnung geht zwingend an die Eltern"],"answer":0,"hint":"Wer bezahlt zuerst?","explanation":"Tiers garant beschreibt die Zahlungsbeziehung. Ob die Person vor der Erstattung schon bezahlt hat und wie der Ablauf organisiert wird, ist damit nicht in jedem Einzelfall festgelegt.","source_refs":["CH-BAG-COST"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-06-document","optional":true,"context":"Diese Rechnung betrifft Lea, eine erwachsene fiktive Versicherte. Alle 420 Franken sind im Fall gedeckte ambulante Behandlungskosten. Ihre Franchise von 300 Franken ist noch ganz offen; der gewöhnliche Selbstbehalt ist noch nicht ausgeschöpft. Wir lassen Spitaltage, besondere Medikamente und Ausnahmen ausdrücklich weg.","context_document_required":true}],"vertiefen":["ga-05-05","ga-05-04"],"source_refs":["CH-BAG-COST"],"contentRevision":"r159-audit-2026-11-07","reviewStatus":"SOURCE_CHECKED_EDITORIAL_REPLACEMENT_SPECIALIST_REVIEW_PENDING","checkedOn":"2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","context_policy":"Keep the complete fictional document available beside every question; never grade from an unseen case."},{"id":"gl-07","nr":7,"kurz":"Mietvertrag","titel":"Der Mietvertrag: die wichtigen Felder","bild":"🏠","wozu":"Du liest vereinbarte Mietkosten und Kündigungsbedingungen in einem fiktiven Vertrag.","einstieg":"Ein Mietvertrag regelt ein Nutzungsrecht, nicht den Erwerb der Wohnung. Im fiktiven Dokument finden wir Miete, Nebenkosten, Kaution und ausdrücklich vereinbarte ordentliche Kündigungsbedingungen. Der Kurs entscheidet keinen realen Mietfall und berechnet keine persönliche Frist.","ziele":["Nettomiete, Nebenkosten und Bruttomiete unterscheiden","Verstehen, wie die Kaution funktioniert","Kündigungsfrist und Kündigungstermin finden"],"begriffe":[["Nettomiete","Miete für die Wohnung selbst."],["Nebenkosten","Heizung, Warmwasser, Hauswart usw. Oft als Akonto: Vorauszahlung, die einmal im Jahr abgerechnet wird."],["Kaution","Sicherheit für die Vermieterin. Höchstens drei Monatsmieten. Sie liegt auf einem Mietkautionskonto auf deinen Namen."],["Kündigungsfrist","So lange vor dem Auszug musst du kündigen."]],"doc":{"art":"Mietvertrag","kopfL":["Mietvertrag für Wohnräume (Auszug)","Muster Immobilien AG, Vermieterin"],"kopfR":["Mieterin: Lea Beispiel","Objekt: 2½-Zimmer, Seeweg 4, 8706 Meilen"],"titel":"Mietvertrag · Seite 1","unter":"Vereinfachte Lern-Nachbildung","teile":[{"t":"zeilen","zeilen":[["Mietbeginn","01.04.2027",1],["Nettomietzins pro Monat","1’250.00",2],["Nebenkosten (Akonto) pro Monat","180.00",3],["Bruttomietzins pro Monat","1’430.00",4,"stark linie"],["Sicherheitsleistung (Kaution)","3’750.00",5],["Kündigungsfrist","3 Monate",6],["Kündigungstermine","Ende März, Juni, September (nicht Dezember)",7]]},{"t":"kasten","titel":"Wichtig","text":"Die Kündigung muss schriftlich erfolgen und spätestens am letzten Tag vor Beginn der Frist bei der Vermieterin eintreffen.","n":8}],"fuss":"Vereinfachte Lern-Nachbildung, kein amtliches Formular und nicht für eine Zahlung, Erklärung oder einen Antrag verwendbar. Muster mit fiktiven Werten. Massgebend sind dein Vertrag, das Obligationenrecht und die örtlichen Regeln. Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","case_date_policy":"Any 2027/2031 date belongs to an invented story, not a claim that future law has been verified. Substantive guidance checked on 2026-11-07."},"tour":[[1,"Mietparteien","Im Muster stehen Vermieterschaft und Mieterin. Der Vertrag betrifft ein Nutzungsrecht an der beschriebenen Wohnung."],[2,"Nettomiete","Die Miete für die Wohnung selbst."],[3,"Nebenkosten","Vorauszahlung für Heizung, Wasser usw. Einmal im Jahr kommt die Abrechnung. Dann zahlst du nach oder bekommst Geld zurück."],[4,"Bruttomiete","Das zahlst du wirklich jeden Monat: 1’250 + 180 = 1’430 Franken."],[5,"Kaution im Beispiel","Im Muster ist eine Geldkaution für Wohnraum vereinbart. Sie liegt auf einem Bankkonto auf den Namen der Mieterin. Sie ist gebundenes Geld, keine zusätzliche Monatsmiete. Freigabe und allfällige Ansprüche sind gesondert zu klären."],[6,"Vereinbarte ordentliche Frist","Dieses Muster nennt drei Monate. Das ist die Voraussetzung der folgenden Leseaufgabe, keine Berechnung für einen anderen Vertrag."],[7,"Ordentliche Termine und andere Wege","Die genannten Termine betreffen die ordentliche Kündigung dieses Musters. Vorzeitige Rückgabe, eine Vereinbarung oder andere gesetzliche Gründe sind davon zu unterscheiden. Die Bedingungen werden hier nicht für eine Person geprüft."],[8,"Form und Eingang","Der Fall verlangt eine schriftliche, rechtzeitig zugegangene Erklärung. Welche Form, Unterschriften und Empfangsdaten im wirklichen Fall gelten, muss an den massgebenden Unterlagen geprüft werden."]],"beispiel":"Lea braucht zum Einzug: Kaution 3’750 + erste Bruttomiete 1’430 = 5’180 Franken. Das muss sie vor dem Einzug bereit haben.","fehler":["Die Wohnungsmiete mit Eigentum verwechseln.","Den Versandtag mit dem rechtzeitigen Eingang gleichsetzen.","Ordentliche Vertragstermine mit allen denkbaren Möglichkeiten einer vorzeitigen Rückgabe gleichsetzen."],"fragen":[{"id":"gl-07-q1","type":"numeric","prompt":"Wie viel Miete zahlt Lea jeden Monat insgesamt?","answer":1430,"tolerance":0.01,"unit":"CHF","hint":"Nettomiete plus Nebenkosten.","explanation":"1’250 + 180 = 1’430 Franken Bruttomiete.","source_refs":["CH-ZH-EARLY-RETURN","CH-ZH-DEPOSIT"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-07-document","optional":true,"context":"Ein Mietvertrag regelt ein Nutzungsrecht, nicht den Erwerb der Wohnung. Im fiktiven Dokument finden wir Miete, Nebenkosten, Kaution und ausdrücklich vereinbarte ordentliche Kündigungsbedingungen. Der Kurs entscheidet keinen realen Mietfall und berechnet keine persönliche Frist.","context_document_required":true},{"id":"gl-07-q2","type":"mc","prompt":"Wohin gehört die Kaution?","options":["Auf ein Mietkautionskonto auf den Namen der Mieterin","Bar in die Hand der Vermieterin","Aufs Privatkonto der Vermieterin","Sie wird mit der ersten Miete verrechnet"],"answer":0,"hint":"Das Geld bleibt deines.","explanation":"Die Kaution liegt auf einem gesperrten Konto auf deinen Namen. So ist sie geschützt.","source_refs":["CH-ZH-EARLY-RETURN","CH-ZH-DEPOSIT"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-07-document","optional":true,"context":"Ein Mietvertrag regelt ein Nutzungsrecht, nicht den Erwerb der Wohnung. Im fiktiven Dokument finden wir Miete, Nebenkosten, Kaution und ausdrücklich vereinbarte ordentliche Kündigungsbedingungen. Der Kurs entscheidet keinen realen Mietfall und berechnet keine persönliche Frist.","context_document_required":true},{"id":"gl-07-q3","type":"mc","prompt":"Reine Leseaufgabe: Das Muster erlaubt die ordentliche Beendigung Ende September und verlangt drei volle Monate Vorlauf. Welcher Eingangstermin folgt unter diesen Fallannahmen?","options":["Spätestens am 30. Juni","Spätestens am 31. August","Spätestens am 30. September","Wann sie will"],"answer":0,"hint":"Drei Monate vor dem Termin.","explanation":"Im vereinfachten Muster entspricht Ende Juni dem beschriebenen Vorlauf vor Ende September. Das ist keine Fristberechnung für einen realen Mietvertrag oder eine ausserordentliche Beendigung.","source_refs":["CH-ZH-EARLY-RETURN","CH-ZH-DEPOSIT"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-07-document","optional":true,"context":"Ein Mietvertrag regelt ein Nutzungsrecht, nicht den Erwerb der Wohnung. Im fiktiven Dokument finden wir Miete, Nebenkosten, Kaution und ausdrücklich vereinbarte ordentliche Kündigungsbedingungen. Der Kurs entscheidet keinen realen Mietfall und berechnet keine persönliche Frist.","context_document_required":true}],"vertiefen":["ga-18-01","ga-18-02","ga-04-05"],"source_refs":["CH-ZH-EARLY-RETURN","CH-ZH-DEPOSIT"],"contentRevision":"r159-audit-2026-11-07","reviewStatus":"SOURCE_CHECKED_EDITORIAL_REPLACEMENT_SPECIALIST_REVIEW_PENDING","checkedOn":"2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","context_policy":"Keep the complete fictional document available beside every question; never grade from an unseen case."},{"id":"gl-08","nr":8,"kurz":"Steuererklärung","titel":"Die Steuererklärung: so ist sie aufgebaut","bild":"📑","wozu":"Du unterscheidest Einkommens-, Abzugs- und Vermögensangaben in einem Lernschema.","einstieg":"Wir lesen ein Schema, kein kantonales Steuerformular. Der Fall nimmt eine erwachsene Person im ordentlichen Verfahren und ein ganzes Kalenderjahr an. Ob jemand eine Erklärung einreichen muss und welche Positionen gelten, hängt unter anderem vom Verfahren, Kanton und Steuerjahr ab. Insbesondere Quellensteuerfälle folgen nicht automatisch diesem Beispiel.","ziele":["Einkommen, Abzüge und Vermögen unterscheiden","Wissen, welcher Beleg wohin gehört","Verstehen, dass ein Abzug keine Rückzahlung ist"],"begriffe":[["Einkommen","Lohn und andere Einnahmen im Steuerjahr."],["Abzug","Kosten, die du vom Einkommen abziehen darfst, zum Beispiel Arbeitsweg."],["Vermögen","Was du am 31. Dezember besitzt, zum Beispiel Geld auf dem Konto."],["Wertschriftenverzeichnis","Liste aller Konten und Wertschriften mit Stand am 31.12."]],"doc":{"art":"Steuererklärung","kopfL":["Erfundenes Lernschema mit Jahresbezug","Kein amtlicher Kanton und keine Einreichung"],"kopfR":["Lea Beispiel","geboren 2008, ledig"],"titel":"Steuerliche Angaben unterscheiden (Schema)","unter":"Feldnummern und Abzüge sind je nach Kanton anders","teile":[{"t":"abschnitt","titel":"A  Einkünfte"},{"t":"ziffern","zeilen":[["A1","Lohn aus unselbständiger Arbeit (Lohnausweis Ziffer 11)","52’945",1,"stark"],["A2","Zinsen und Erträge (laut Wertschriftenverzeichnis)","3",2]]},{"t":"abschnitt","titel":"B  Abzüge"},{"t":"ziffern","zeilen":[["B1","Berufsauslagen: Fahrkosten (ÖV-Abo)","2’100",3],["B2","Berufsauslagen: Verpflegung, übrige","…",4],["B3","Einzahlungen Säule 3a (Bescheinigung)","1’200",5],["B4","Versicherungsprämien","…",6]]},{"t":"abschnitt","titel":"C  Vermögen am 31.12."},{"t":"ziffern","zeilen":[["C1","Bankguthaben (laut Wertschriftenverzeichnis)","3’398",7]]},{"t":"kasten","titel":"Beilagen","text":"Lohnausweis, Bescheinigung Säule 3a, Kontoauszüge per 31.12., Prämienbestätigung","n":8}],"fuss":"Vereinfachte Lern-Nachbildung, kein amtliches Formular und nicht für eine Zahlung, Erklärung oder einen Antrag verwendbar. Lern-Nachbildung, kein amtliches Formular. Verwende immer die Unterlagen deines Kantons. Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","case_date_policy":"Any 2027/2031 date belongs to an invented story, not a claim that future law has been verified. Substantive guidance checked on 2026-11-07."},"tour":[[1,"Bescheinigter Lohn","Im Beispiel wird Ziffer 11 des Lohnausweises gelesen. Die Zuordnung im wirklichen Verfahren erfolgt anhand der zuständigen Wegleitung."],[2,"Erträge","Der Fall unterscheidet einen Ertrag während des Jahres von einem Guthaben am Jahresende. Das sind unterschiedliche Angaben."],[3,"Arbeitsweg als Prüffrage","Die 2100 Franken sind eine Fallangabe. Ob und wie viel davon abzugsfähig ist, wird hier nicht entschieden; Voraussetzungen und Grenzen können sich nach Steuerart und Jahr unterscheiden."],[4,"Weitere Positionen","Die Punkte markieren ungeklärte Angaben. Fehlende Informationen dürfen nicht durch erfundene Pauschalen ersetzt werden."],[5,"Bescheinigung zur Säule 3a","Eine Bescheinigung nennt eine tatsächliche Einzahlung. Die persönliche Berechtigung und die anwendbare Grenze sind separate Fragen. Das Schema entscheidet sie nicht."],[6,"Versicherungsprämien","Bezahlte Prämien sind nicht automatisch in voller Höhe abziehbar. Die Übung bleibt eine Einordnung von Belegen."],[7,"Stichtag im Fall","Dieser Fall verwendet den 31. Dezember eines ganzen Steuerjahres. Unterjährige oder andere besondere Situationen brauchen ihre eigenen Vorgaben."],[8,"Belege und Einreichung","Wir ordnen nur fiktive Belege. Was einzureichen oder aufzubewahren ist, steht in der zuständigen aktuellen Wegleitung. Hier wird nichts eingereicht."]],"beispiel":"Reines Rechenmodell: Ein angenommener zulässiger Abzug von 1200 Franken verringert eine ebenfalls nur angenommene Bemessungsgrundlage. Wenn für genau diesen Bereich ein konstanter Grenzsteuersatz von 15 % unterstellt wird, beträgt die Modelländerung 180 Franken. Eine reale Ersparnis oder Abzugsberechtigung wird nicht bestimmt.","fehler":["Ein Lernschema als amtliches Formular verwenden.","Aus einem Betrag auf einer Quittung ohne weitere Prüfung einen zulässigen Abzug ableiten.","Einen angenommenen Grenzsteuersatz mit der durchschnittlichen Steuerbelastung verwechseln."],"fragen":[{"id":"gl-08-q1","type":"mc","prompt":"Woher nimmt Lea die Zahl für A1 (Lohn)?","options":["Aus dem Lohnausweis, Ziffer 11","Aus der Lohnabrechnung vom Dezember","Aus dem Kontoauszug","Aus dem Arbeitsvertrag"],"answer":0,"hint":"Der Jahresbeleg der Firma.","explanation":"Der Nettolohn steht im Lohnausweis unter Ziffer 11.","source_refs":["CH-ESTV-SALARY","CH-ZH-TAX","CH-ZH-WITHHOLDING","CH-BSV-3A"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-08-document","optional":true,"context":"Wir lesen ein Schema, kein kantonales Steuerformular. Der Fall nimmt eine erwachsene Person im ordentlichen Verfahren und ein ganzes Kalenderjahr an. Ob jemand eine Erklärung einreichen muss und welche Positionen gelten, hängt unter anderem vom Verfahren, Kanton und Steuerjahr ab. Insbesondere Quellensteuerfälle folgen nicht automatisch diesem Beispiel.","context_document_required":true},{"id":"gl-08-q2","type":"mc","prompt":"Welchen Vermögensstichtag verwendet das fiktive Beispiel mit einem ganzen Kalenderjahr?","options":["Am 31. Dezember","Am 1. Januar des Folgejahres, wenn die Erklärung kommt","Am Tag der Einreichung","Am Geburtstag"],"answer":0,"hint":"Stichtag Ende Jahr.","explanation":"Das Schema verwendet den 31. Dezember. Es bildet keine unterjährige oder andere besondere Steuerpflicht ab.","source_refs":["CH-ESTV-SALARY","CH-ZH-TAX","CH-ZH-WITHHOLDING","CH-BSV-3A"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-08-document","optional":true,"context":"Wir lesen ein Schema, kein kantonales Steuerformular. Der Fall nimmt eine erwachsene Person im ordentlichen Verfahren und ein ganzes Kalenderjahr an. Ob jemand eine Erklärung einreichen muss und welche Positionen gelten, hängt unter anderem vom Verfahren, Kanton und Steuerjahr ab. Insbesondere Quellensteuerfälle folgen nicht automatisch diesem Beispiel.","context_document_required":true},{"id":"gl-08-q3","type":"numeric","prompt":"Reine Modellrechnung: Für einen angenommenen zulässigen Abzug von 1200 Franken wird ein konstanter Grenzsteuersatz von 15 % unterstellt. Wie gross ist die berechnete Änderung?","answer":180,"tolerance":0.5,"unit":"CHF","hint":"15 % von 1’200.","explanation":"1200 × 0,15 = 180 Franken. Das Modell bestätigt weder einen realen Abzug noch eine konkrete Steuerersparnis und verwendet keinen durchschnittlichen Steuersatz.","source_refs":["CH-ESTV-SALARY","CH-ZH-TAX","CH-ZH-WITHHOLDING","CH-BSV-3A"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-08-document","optional":true,"context":"Wir lesen ein Schema, kein kantonales Steuerformular. Der Fall nimmt eine erwachsene Person im ordentlichen Verfahren und ein ganzes Kalenderjahr an. Ob jemand eine Erklärung einreichen muss und welche Positionen gelten, hängt unter anderem vom Verfahren, Kanton und Steuerjahr ab. Insbesondere Quellensteuerfälle folgen nicht automatisch diesem Beispiel.","context_document_required":true}],"vertiefen":["ga-06-01","ga-06-03","ga-07-02","ga-07-04"],"source_refs":["CH-ESTV-SALARY","CH-ZH-TAX","CH-ZH-WITHHOLDING","CH-BSV-3A"],"contentRevision":"r159-audit-2026-11-07","reviewStatus":"SOURCE_CHECKED_EDITORIAL_REPLACEMENT_SPECIALIST_REVIEW_PENDING","checkedOn":"2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","context_policy":"Keep the complete fictional document available beside every question; never grade from an unseen case."},{"id":"gl-09","nr":9,"kurz":"AHV-Konto","titel":"Dein AHV-Konto: Lücken früh erkennen","bild":"👵","wozu":"Du erkennst eine auffällige Leerstelle im Muster und weisst, welche Angaben für deren Klärung fehlen.","einstieg":"Das individuelle AHV-Konto erfasst beitragsrelevante Angaben wie Einkommen und Beitragszeiten. Es ist kein persönliches Sparkonto. Eine leere Zeile muss geklärt werden: War die Person versichert und beitragspflichtig? Fehlt nur eine Meldung? Nachzahlungen sind grundsätzlich nur für bestimmte jüngere Beitragslücken möglich, wenn damals AHV-Versicherung bestand. Die Lernseite entscheidet das nicht.","ziele":["Einen AHV-Kontoauszug lesen","Eine Beitragslücke erkennen","Wissen, was du dagegen tun kannst"],"begriffe":[["Ausgleichskasse","Stelle, die AHV-Beiträge einzieht und dein Konto führt."],["Beitragslücke","Ein Jahr ohne genügend Beiträge."],["Nichterwerbstätige","Wer nicht arbeitet, zum Beispiel Studierende, muss ab dem Jahr nach dem 20. Geburtstag selbst Mindestbeiträge zahlen."]],"doc":{"art":"Kontoauszug AHV","kopfL":["Ausgleichskasse Muster","Auszug aus dem individuellen Konto (IK)"],"kopfR":["Lea Beispiel","AHV-Nr. 756.0000.0000.00 (Muster)"],"titel":"Individueller Kontoauszug","unter":"Stand 15.02.2031","teile":[{"t":"tabelle","kopf":["Jahr","Beitragsmonate","Arbeitgeber / Kasse","Einkommen CHF"],"zeilen":[["2027","12","Velowerk Muster AG","59’800",1],["2028","12","Velowerk Muster AG","61’100",2],["2029","–","–","–",3],["2030","12","Pflegezentrum Muster","63’400",4]]}],"fuss":"Vereinfachte Lern-Nachbildung, kein amtliches Formular und nicht für eine Zahlung, Erklärung oder einen Antrag verwendbar. Muster mit fiktiven Werten. Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","case_date_policy":"Any 2027/2031 date belongs to an invented story, not a claim that future law has been verified. Substantive guidance checked on 2026-11-07."},"tour":[[1,"Eingetragener Zeitraum","Das Muster zeigt zwölf Beitragsmonate und ein Einkommen. Das ist ein Eintrag, keine vollständige Rentenprüfung."],[2,"Nächster Eintrag","Auch für 2028 stehen Daten im Muster. Ob sie sachlich vollständig sind, würde man mit den eigenen Belegen prüfen."],[3,"Leerstelle 2029","Hier fehlen Angaben. Der Fall nennt einen Auslandsaufenthalt. Ob das eine Melde-, Beitrags- oder Versicherungslücke ist, bleibt offen."],[4,"Eintrag 2030","Ein späterer Eintrag erklärt die frühere Leerstelle nicht automatisch. Die Jahresfolge hilft, eine konkrete Rückfrage vorzubereiten."]],"beispiel":"Im erfundenen Auszug fehlen 2029 Angaben. Lea war damals im Ausland. Allein das Alter der Leerstelle beweist nicht, dass Nachzahlen möglich ist. Zuerst müsste die Ausgleichskasse klären, ob Versicherung und Beitragspflicht bestanden oder eine Meldung fehlt. Das Ergebnis bleibt im Fall offen.","fehler":["Eine fehlende Zeile ohne weitere Angaben als endgültige Beitragslücke behandeln.","Annehmen, jedes Auslandsjahr lasse sich innerhalb von fünf Jahren nachkaufen.","Das individuelle Konto mit einem eigenen angesparten Kapitalbetrag verwechseln."],"fragen":[{"id":"gl-09-q1","type":"numeric","prompt":"Für welches Jahr fehlen im fiktiven Auszug Angaben?","answer":2029,"tolerance":0,"hint":"Zeile ohne Einträge.","explanation":"Die Zeile 2029 ist leer. Damit ist eine Auffälligkeit erkannt, nicht deren Ursache oder Rechtsfolge festgestellt.","source_refs":["CH-BSV-GAPS","CH-BSV-RETIREMENT"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-09-document","optional":true,"context":"Das individuelle AHV-Konto erfasst beitragsrelevante Angaben wie Einkommen und Beitragszeiten. Es ist kein persönliches Sparkonto. Eine leere Zeile muss geklärt werden: War die Person versichert und beitragspflichtig? Fehlt nur eine Meldung? Nachzahlungen sind grundsätzlich nur für bestimmte jüngere Beitragslücken möglich, wenn damals AHV-Versicherung bestand. Die Lernseite entscheidet das nicht.","context_document_required":true},{"id":"gl-09-q2","type":"numeric","prompt":"Welche grundsätzliche Zahl von Jahren nennt die BSV-Erklärung für Nachzahlungen fehlender Beiträge, wenn damalige AHV-Versicherung und weitere Voraussetzungen gegeben sind?","answer":5,"tolerance":0,"unit":"Jahre","hint":"Die zeitliche Grenze ist nur eine von mehreren Voraussetzungen.","explanation":"Fünf Jahre ist die genannte grundsätzliche zeitliche Grenze. Ohne damalige AHV-Versicherung folgt daraus keine Nachzahlungsmöglichkeit. Eine individuelle Klärung bleibt Sache der zuständigen Stelle.","source_refs":["CH-BSV-GAPS","CH-BSV-RETIREMENT"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-09-document","optional":true,"context":"Das individuelle AHV-Konto erfasst beitragsrelevante Angaben wie Einkommen und Beitragszeiten. Es ist kein persönliches Sparkonto. Eine leere Zeile muss geklärt werden: War die Person versichert und beitragspflichtig? Fehlt nur eine Meldung? Nachzahlungen sind grundsätzlich nur für bestimmte jüngere Beitragslücken möglich, wenn damals AHV-Versicherung bestand. Die Lernseite entscheidet das nicht.","context_document_required":true},{"id":"gl-09-q3","type":"mc","prompt":"Die 21-jährige fiktive Studentin lebt in der Schweiz, ist AHV-versichert, nicht erwerbstätig und hat laut Fall keine Ausnahme. Was gilt grundsätzlich?","options":["Auch ohne Lohn besteht eine eigene Beitragspflicht; die Ausgleichskasse klärt die Erhebung","Kein Lohn bedeutet immer keine Beitragspflicht","Die Eltern erfüllen die Pflicht automatisch","Die Hochschule bezahlt immer alles"],"answer":0,"hint":"Nichterwerbstätige werden grundsätzlich ab 1. Januar nach dem 20. Geburtstag beitragspflichtig.","explanation":"Unter den ausdrücklichen Annahmen besteht grundsätzlich eine eigene Beitragspflicht. Ausnahmen und anrechenbare Beiträge dürfen nicht stillschweigend ausgeschlossen werden; hier sind sie als Fallannahme ausgeschlossen.","source_refs":["CH-BSV-GAPS","CH-BSV-RETIREMENT"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-09-document","optional":true,"context":"Das individuelle AHV-Konto erfasst beitragsrelevante Angaben wie Einkommen und Beitragszeiten. Es ist kein persönliches Sparkonto. Eine leere Zeile muss geklärt werden: War die Person versichert und beitragspflichtig? Fehlt nur eine Meldung? Nachzahlungen sind grundsätzlich nur für bestimmte jüngere Beitragslücken möglich, wenn damals AHV-Versicherung bestand. Die Lernseite entscheidet das nicht.","context_document_required":true}],"vertiefen":["ga-08-01","ga-08-02","ga-33-03"],"source_refs":["CH-BSV-GAPS","CH-BSV-RETIREMENT"],"contentRevision":"r159-audit-2026-11-07","reviewStatus":"SOURCE_CHECKED_EDITORIAL_REPLACEMENT_SPECIALIST_REVIEW_PENDING","checkedOn":"2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","context_policy":"Keep the complete fictional document available beside every question; never grade from an unseen case."},{"id":"gl-10","nr":10,"kurz":"Zahlungsbefehl","titel":"Mahnung oder Zahlungsbefehl?","bild":"⚠️","wozu":"Du unterscheidest eine private Zahlungserinnerung von einem amtlichen Zahlungsbefehl und liest die bezeichneten Fristen.","einstieg":"Ein Zahlungsbefehl wird vom Betreibungsamt aufgrund einer geltend gemachten Forderung ausgestellt. Er beweist nicht, dass diese Forderung berechtigt ist. Wir lesen einen erfundenen, vereinfachten Beleg. Die Aufgabe berechnet keine reale Frist und entscheidet weder Zahlung noch Bestreitung.","ziele":["Mahnung und Zahlungsbefehl unterscheiden","Die Fristen 20 Tage und 10 Tage kennen","Wissen, was ein Rechtsvorschlag ist"],"begriffe":[["Betreibung","Amtliches Verfahren, mit dem ein Gläubiger sein Geld eintreiben will."],["Gläubiger","Wer Geld verlangt."],["Schuldner","Wer zahlen soll."],["Rechtsvorschlag","Damit sagst du: «Ich bestreite das.» Das Verfahren stoppt vorerst."]],"doc":{"art":"Zahlungsbefehl","kopfL":["Betreibungsamt Muster","Betreibung Nr. 27-04417"],"kopfR":["Zahlungsbefehl","zugestellt am 03.06.2027"],"titel":"Zahlungsbefehl","unter":"Lern-Nachbildung, kein amtliches Formular","teile":[{"t":"zeilen","zeilen":[["Gläubiger","Fitnessclub Muster GmbH, Zürich",1],["Schuldnerin","Lea Beispiel, Seeweg 4, 8706 Meilen",2],["Forderung","640.00 nebst Zins zu 5 % seit 01.03.2027",3,"stark"],["Grund","Jahresabonnement 2027",4]]},{"t":"kasten","titel":"Die Schuldnerin wird aufgefordert,","text":"den Gläubiger innert 20 Tagen zu befriedigen. Will sie die Forderung bestreiten, muss sie innert 10 Tagen seit Zustellung Rechtsvorschlag erheben (mündlich oder schriftlich beim Betreibungsamt).","n":5},{"t":"kasten","titel":"Rechtsvorschlag","text":"☐ Ich erhebe Rechtsvorschlag.   Datum / Unterschrift: ____________","n":6}],"fuss":"Vereinfachte Lern-Nachbildung, kein amtliches Formular und nicht für eine Zahlung, Erklärung oder einen Antrag verwendbar. Lern-Nachbildung. Bei einer echten Betreibung: Fristen sofort notieren und bei Unsicherheit eine Schuldenberatung fragen. Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","case_date_policy":"Any 2027/2031 date belongs to an invented story, not a claim that future law has been verified. Substantive guidance checked on 2026-11-07."},"tour":[[1,"Gläubiger im Muster","Diese Partei behauptet, eine Forderung zu haben. Der Eintrag beweist ihre Berechtigung noch nicht."],[2,"Adressatin im Muster","Hier steht Lea als betriebene Person. Das ist nicht die Identität der lernenden Person."],[3,"Behaupteter Betrag","Die genannten 640 Franken und Zinsen sind Angaben der geltend gemachten Forderung, nicht ein von der Lernseite bestätigter Anspruch."],[4,"Forderungsgrund","Der Text beschreibt, woraus die behauptete Forderung stammen soll. Die Unterlagen müssten zur Prüfung herangezogen werden."],[5,"Genannte Fristen","Das Muster nennt grundsätzlich zehn Tage für Rechtsvorschlag und zwanzig Tage für Zahlung. Es berechnet kein konkretes Enddatum. Zustellung, Fristenregeln und besondere Verfahren brauchen eine eigene Prüfung."],[6,"Wirkung des Rechtsvorschlags","Rechtsvorschlag hemmt die Fortsetzung der Betreibung zunächst. Die Forderung wird dadurch nicht bezahlt oder gelöscht. Ob und wie vorzugehen ist, wird hier nicht für eine Person entschieden."]],"beispiel":"Lea hat das Abo im Dezember fristgerecht gekündigt und hat die Bestätigung. Sie erhebt innert 10 Tagen Rechtsvorschlag beim Betreibungsamt und bewahrt die Kündigungsbestätigung auf.","fehler":["Den Zahlungsbefehl als richterliche Bestätigung der Schuld lesen.","Eine allgemeine Tageszahl ungeprüft als persönliches Enddatum verwenden.","Rechtsvorschlag mit Erlass oder Bezahlung einer Schuld verwechseln."],"fragen":[{"id":"gl-10-q1","type":"numeric","prompt":"Welche grundsätzliche Tageszahl nennt das fiktive Dokument für Rechtsvorschlag?","answer":10,"tolerance":0,"unit":"Tage","hint":"Steht im Kasten 5.","explanation":"Der Mustertext nennt zehn Tage. Diese Leseaufgabe berechnet kein persönliches Fristende.","source_refs":["CH-ZURICH-PAYMENTORDER"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-10-document","optional":true,"context":"Ein Zahlungsbefehl wird vom Betreibungsamt aufgrund einer geltend gemachten Forderung ausgestellt. Er beweist nicht, dass diese Forderung berechtigt ist. Wir lesen einen erfundenen, vereinfachten Beleg. Die Aufgabe berechnet keine reale Frist und entscheidet weder Zahlung noch Bestreitung.","context_document_required":true},{"id":"gl-10-q2","type":"mc","prompt":"Wer schickt einen Zahlungsbefehl?","options":["Das Betreibungsamt","Die Firma, die Geld will","Die Polizei","Die Bank"],"answer":0,"hint":"Es ist eine Behörde.","explanation":"Den Zahlungsbefehl stellt das Betreibungsamt zu. Eine Mahnung schreibt dagegen die Firma selbst.","source_refs":["CH-ZURICH-PAYMENTORDER"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-10-document","optional":true,"context":"Ein Zahlungsbefehl wird vom Betreibungsamt aufgrund einer geltend gemachten Forderung ausgestellt. Er beweist nicht, dass diese Forderung berechtigt ist. Wir lesen einen erfundenen, vereinfachten Beleg. Die Aufgabe berechnet keine reale Frist und entscheidet weder Zahlung noch Bestreitung.","context_document_required":true},{"id":"gl-10-q3","type":"mc","prompt":"Welche allgemeine Wirkung beschreibt der Mustertext für Rechtsvorschlag?","options":["Die Fortsetzung ist zunächst gehemmt; die Forderung verschwindet dadurch nicht","Die behauptete Schuld ist automatisch gelöscht","Lea schuldet automatisch das Doppelte","Es hat keine verfahrensrechtliche Bedeutung"],"answer":0,"hint":"Er ist ein Widerspruch.","explanation":"Für eine Fortsetzung muss der Rechtsvorschlag beseitigt sein. Daraus folgt weder ein Erlass noch eine Bestätigung der Forderung.","source_refs":["CH-ZURICH-PAYMENTORDER"],"contentRevision":"r159-audit-2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","document_id":"gl-10-document","optional":true,"context":"Ein Zahlungsbefehl wird vom Betreibungsamt aufgrund einer geltend gemachten Forderung ausgestellt. Er beweist nicht, dass diese Forderung berechtigt ist. Wir lesen einen erfundenen, vereinfachten Beleg. Die Aufgabe berechnet keine reale Frist und entscheidet weder Zahlung noch Bestreitung.","context_document_required":true}],"vertiefen":["ga-11-02","ga-20-04","ga-32-05"],"source_refs":["CH-ZURICH-PAYMENTORDER"],"contentRevision":"r159-audit-2026-11-07","reviewStatus":"SOURCE_CHECKED_EDITORIAL_REPLACEMENT_SPECIALIST_REVIEW_PENDING","checkedOn":"2026-11-07","fictional_case":true,"education_notice":"Fiktives Lernbeispiel. Keine Finanz-, Steuer-, Versicherungs- oder Rechtsberatung. Keine Beurteilung deiner persönlichen Situation.","context_policy":"Keep the complete fictional document available beside every question; never grade from an unseen case."}],"sources":[{"id":"CH-BSV-CONTRIB","title":"BSV: Beitraege im Ueberblick","url":"https://www.bsv.admin.ch/de/beitraege-im-ueberblick","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["Employee AHV/IV/EO rate 5.3%; employee ALV rate 1.1% up to the applicable ceiling. Do not infer entitlement from payment of contributions."]},{"id":"CH-BSV-GAPS","title":"BSV: Versicherungs- und Beitragsluecken","url":"https://www.bsv.admin.ch/de/versicherungs-und-beitragsluecken-in-der-ahv","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["Insurance gaps differ from unpaid contributions or missing reports. Different correction mechanisms exist; a blank year alone is insufficient evidence."]},{"id":"CH-BSV-RETIREMENT","title":"BSV: Altersvorsorge","url":"https://www.bsv.admin.ch/de/altersvorsorge","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["Ordinary back-payment of missing contributions is limited to the relevant recent five years and requires AHV insurance during that period."]},{"id":"CH-BAG-UVG","title":"BAG: Wer ist obligatorisch unfallversichert?","url":"https://www.bag.admin.ch/de/unfallversicherung-wer-ist-obligatorisch-versichert","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["Non-occupational accident cover requires at least eight weekly hours with the same employer. Unemployed people can also be compulsorily covered."]},{"id":"CH-BAG-SUSPEND","title":"BAG: Sistierung der Unfalldeckung","url":"https://www.bag.admin.ch/de/krankenversicherung-zur-sistierung-der-unfalldeckung-berechtigte-versicherte","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["Suspension under health insurance requires full UVG cover and an application/evidence. It is not decided by a learning app."]},{"id":"CH-SUVA-UNEMPLOYED","title":"Suva: Versicherungsschutz fuer Arbeitslose","url":"https://www.suva.ch/de-ch/versicherung/unfallversicherung/unfallversicherung-bei-arbeitslosigkeit/versicherungsschutz-fuer-arbeitslose","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["Automatic Suva coverage when unemployment-compensation requirements are met; includes waiting and suspension days. Prior employment cover can continue for a limited period. A job change is not proof of absent cover."]},{"id":"CH-BAG-COST","title":"BAG: Kostenbeteiligung","url":"https://www.bag.admin.ch/de/krankenversicherung-kostenbeteiligung-fuer-in-der-schweiz-wohnhafte-versicherte","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["Standard adult deductible and ordinary coinsurance must be distinguished from hospital contributions, exceptions and non-covered services."]},{"id":"CH-BAG-DRUG","title":"BAG: Differenzierter Selbstbehalt bei Arzneimitteln","url":"https://www.bag.admin.ch/de/differenzierter-selbstbehalt-bei-arzneimitteln","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["Certain medicines can attract higher coinsurance. Its treatment toward the ordinary maximum means an unqualified never-more-than-700 claim is wrong."]},{"id":"CH-ESTV-SALARY","title":"ESTV: Lohnausweis/Rentenbescheinigung","url":"https://www.estv.admin.ch/de/lohnausweis-rentenbescheinigung","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["The official certificate separates gross pay, contributions, occupational-pension contributions, net pay and expense reimbursements."]},{"id":"CH-ESTV-SALARY-PDF","title":"ESTV salary certificate guide, 2026","url":"https://www.estv.admin.ch/dam/de/sd-web/afP1GDFr8gE3/dbst-form-lohna-wegleitung-2026-de.pdf","retrieved_on":"2026-11-07","kind":"official_pdf_screenshot_checked","document_version":"1 January 2026","supported_facts":["Page 2 visually checked: numbered salary certificate. Field 11 is certified net salary; it is not every monthly bank transfer."]},{"id":"CH-SIX-QR","title":"SIX: QR bill standard","url":"https://www.six-group.com/de/products-services/banking-services/payment-standardization/standards/qr-bill.html","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["QR data are also human-readable so the recipient can compare the data. The source identifies current and future standard versions; do not silently activate future rules."]},{"id":"CH-SIX-FAQ","title":"SIX: Payment standards FAQ","url":"https://www.six-group.com/de/products-services/banking-services/payment-standardization/downloads-faq/faq.html","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["QR-IBAN with QR reference; IBAN with creditor reference; IBAN without reference are distinct combinations. A replica must not pretend to be a valid payable bill."]},{"id":"CH-ZH-EARLY-RETURN","title":"Zurich courts: Vorzeitige Rueckgabe","url":"https://www.gerichte-zh.ch/de/themen/miete/kuendigung-rueckgabe/vorzeitige-rueckgabe-der-mietsache","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["Ordinary notice dates are not the only way a tenancy can end; early return has separate conditions."]},{"id":"CH-ZH-DEPOSIT","title":"Zurich courts: Sicherheitsleistungen des Mieters","url":"https://www.gerichte-zh.ch/de/themen/miete/rechte-und-pflichten/mietdepot","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["Residential cash/security deposits are subject to statutory rules, including deposit in the tenant name; release is not an unconditional automatic refund."]},{"id":"CH-ZH-TAX","title":"Zurich: Tax return for natural persons","url":"https://www.zh.ch/de/steuern-finanzen/steuern/steuern-natuerliche-personen/steuererklaerung-natuerliche-personen.html","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["Use the official year-specific filing material. A generic learning schema is not an official canton form."]},{"id":"CH-ZH-WITHHOLDING","title":"Zurich: Quellensteuerpflichtige Personen","url":"https://www.zh.ch/de/steuern-finanzen/steuern/quellensteuer/Quellensteuerpflichtige-Personen.html","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["Withholding-tax and subsequent ordinary assessment rules mean turning 18 does not establish one universal filing procedure for every person."]},{"id":"CH-BSV-3A","title":"BSV: Third pillar","url":"https://www.bsv.admin.ch/de/die-dritte-saeule","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["Eligibility, actual payment, annual ceiling and access restrictions are distinct questions. The current package is not a personal deduction or pension tool."]},{"id":"CH-ZURICH-PAYMENTORDER","title":"City Zurich: Meaning of a payment order","url":"https://www.stadt-zuerich.ch/de/lebenslagen/einwohner-services/betreibungen/betreibung-zahlungsbefehl-erhalten/zahlungsbefehl.html","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["The payment order is issued from the creditor allegations without adjudicating the claim. General ten-/twenty-day periods require procedural context; an objection does not erase the debt."]},{"id":"CH-LEHRPLAN-WAH","title":"Lehrplan 21: WAH.2.3","url":"https://v-fe.lehrplan.ch/index.php?code=a%7C6%7C3%7C2%7C0%7C3","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["Includes budgets, fixed/variable costs, payment methods, contract conditions and debt. Therefore nobody learns this at school is an indefensible blanket claim."]},{"id":"CH-SBFI-EBMP","title":"SBFI: Federal vocational baccalaureate examination","url":"https://www.sbfi.admin.ch/de/eidgenoessische-berufsmaturitaetspruefung-ebmp","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["Separate current and transitional requirements. r159 contains newer cohort handling; do not automatically reopen a corrected r155 defect."]},{"id":"CH-SBFI-EBMP-PDF","title":"SBFI guidelines for examinations from 2027","url":"https://www.sbfi.admin.ch/dam/de/sd-web/gII4b6y32f7x/260522_Richtlinien-EBMP%20ab%202027_DE_def.pdf","retrieved_on":"2026-11-07","kind":"official_pdf_screenshot_checked","document_version":"1 October 2026","supported_facts":["Cover visually checked: 1 October 2026, examinations from 2027. The PDF covers the current regime, not proof of Stoffknacker competence coverage."]},{"id":"CH-EDOB","title":"EDOB: Information duties","url":"https://www.edoeb.admin.ch/de/informationspflicht","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["Privacy disclosures must reflect the controller, purposes, relevant recipients and cross-border circumstances. No-account does not mean no network processing."]},{"id":"CH-IGE","title":"IGE: Copyright in schools","url":"https://www.ige.ch/de/etwas-schuetzen/urheberrecht/ein-werk-nutzen/urheberrecht-in-schulen","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["Classroom exceptions do not automatically authorise publication on an open website."]},{"id":"CH-FINMA","title":"FINMA: Financial services legal framework","url":"https://www.finma.ch/de/dokumentation/rechtsgrundlagen/gesetze-und-verordnungen/finanzdienstleistungen/","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["Framework reference for review of the service. Educational disclaimers are not a certification or a substitute for reviewing actual functions."]},{"id":"W3C-CONTRAST","title":"WCAG 2.2 contrast","url":"https://www.w3.org/TR/WCAG22/","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["Ordinary text needs 4.5:1 for AA; qualifying large text 3:1. The measured white-on-green 2.09:1 fails either benchmark."]},{"id":"W3C-DIALOG","title":"WAI-ARIA modal dialog pattern","url":"https://www.w3.org/WAI/ARIA/apg/patterns/dialog-modal/","retrieved_on":"2026-11-07","kind":"official_primary","document_version":null,"supported_facts":["Modal keyboard focus stays inside; Escape closes; focus returns appropriately."]},{"id":"JSDELIVR-PRIVACY","title":"jsDelivr official repository privacy policy","url":"https://raw.githubusercontent.com/jsdelivr/jsdelivr/master/Privacy%20Policy.md","retrieved_on":"2026-11-07","kind":"official_repository","document_version":"23 November 2023","supported_facts":["Operator: Volentio JSD Limited. CDN usage may include IP, browser and restricted referrer/request metadata. The policy does not promise zero IP processing or a fixed universal raw-log deletion period."]},{"id":"JSDELIVR-PAGE","title":"jsDelivr privacy landing page","url":"https://www.jsdelivr.com/terms/privacy-policy","retrieved_on":"2026-11-07","kind":"official_loading_shell","document_version":null,"supported_facts":["Direct page returns a loading shell in the research environment. The official repository text above resolves retrieval, not deployment-specific compliance."]},{"id":"OPENAI-CONSUMER","title":"OpenAI general consumer terms","url":"https://openai.com/policies/terms-of-use/","retrieved_on":"2026-11-07","kind":"official_primary","document_version":"Effective 1 January 2026","supported_facts":["Not the sole applicable reference for a Swiss user or an API application. Follow the European consumer terms and business/API agreement where applicable."]},{"id":"OPENAI-EU","title":"OpenAI Europe terms","url":"https://openai.com/policies/eu-terms-of-use/","retrieved_on":"2026-11-07","kind":"official_primary","document_version":"Updated 16 January 2026","supported_facts":["Applies to relevant consumer use in Switzerland, EEA and UK. Business/API use points to business terms. Output ownership does not establish truth, uniqueness or third-party-rights clearance."]},{"id":"OPENAI-SERVICES","title":"OpenAI Services Agreement","url":"https://openai.com/policies/services-agreement/","retrieved_on":"2026-11-07","kind":"official_primary","document_version":"Effective 1 January 2026; updated 1 December 2025","supported_facts":["Applies to APIs and business/developer services. Customer duties include required end-user permissions and minors consent. The audited file has no configured remote endpoint; do not invent an active API data flow."]}]};
